H.background();
const a = P.a, b = P.b, c = P.c;
const degenerate = Math.abs(a) < 1e-6;            // a = 0 -> not a real two-step equation
const solRaw = degenerate ? 0 : (c - b) / a;       // true solution x (when it exists)
// Make the window always contain the solution AND the y=c line, so the
// intersection dot, its drop-line, and the readout always agree on-screen.
const span = Math.max(10, Math.abs(solRaw) + 2, Math.abs(c) + 2, Math.abs(b) + 2);
const v = H.plot2d({ xMin: -span, xMax: span, yMin: -span, yMax: span });
v.grid(); v.axes();
// line y = a x + b  (if a = 0 this is the horizontal line y = b)
v.fn(x => a * x + b, { color: H.colors.accent, width: 3 });
// target horizontal line y = c
v.line(-span, c, span, c, { color: H.colors.accent2, width: 2, dash: [6, 5] });
const phase = Math.floor((t % 9) / 3);
if (!degenerate) {
  // intersection = the solution x (guaranteed on-screen by the adaptive span)
  v.dot(solRaw, c, { r: 6 + Math.sin(t * 3), fill: H.colors.warn });
  v.line(solRaw, -span, solRaw, c, { color: H.colors.violet, width: 1.5, dash: [4, 4] });
  v.text("x = " + solRaw.toFixed(2), solRaw + span * 0.03, c - span * 0.05, { color: H.colors.warn, size: 13, weight: 700 });
  // moving dot riding the line toward the solution
  const xs = solRaw * (0.5 + 0.5 * Math.sin(t * 0.8));
  v.dot(xs, a * xs + b, { r: 5, fill: H.colors.good });
}
const steps = degenerate
  ? [
      "0·x + " + b.toFixed(1) + " = " + c.toFixed(1),
      "no x term left:   " + b.toFixed(1) + " = " + c.toFixed(1),
      Math.abs(b - c) < 1e-6 ? "true for every x (identity)" : "false -> no solution"
    ]
  : [
      a.toFixed(1) + "x + " + b.toFixed(1) + " = " + c.toFixed(1),
      "subtract " + b.toFixed(1) + ":   " + a.toFixed(1) + "x = " + (c - b).toFixed(1),
      "divide by " + a.toFixed(1) + ":   x = " + solRaw.toFixed(2)
    ];
H.text("Two-step equation:  a*x + b = c", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("step " + (phase + 1) + " / 3:   " + steps[phase], 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "y = a x + b", color: H.colors.accent }, { label: "y = c", color: H.colors.accent2 }], H.W - 170, 28);
